pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        MockGlpManager g = new MockGlpManager();
        c.initialize(
            IERC20(address(1)),
            IERC20(address(2)),
            IRewardRouterV2(address(3)),
            IGlpManager(address(g)),
            address(4),
            address(this)
        );
    }

    function testFuzz_property(uint256 seed, address keeper) public {
        vm.assume(keeper != address(0));
        c.setKeeper(keeper);

        // Track the true pause state while driving an arbitrary-length sequence
        // of keeper actions derived from the fuzzed seed.
        bool expectedPaused = false;
        uint256 steps = bound(seed % 64, 1, 64);
        for (uint256 i = 0; i < steps; i++) {
            vm.prank(keeper);
            if ((seed >> i) & 1 == 0) {
                c.pauseDeposit();
                expectedPaused = true;
            } else {
                c.unpauseDeposit();
                expectedPaused = false;
            }
            // General rule: paused() always reports the actual pause state.
            assertTrue(c.paused() == expectedPaused, "paused() must reflect true pause state");
        }
    }
}

