        // The pause state of a freshly deployed (never-paused) contract must be
        // readable as false from any caller; paused() must reflect the actual
        // internal _paused flag, which starts at false.
        vm.prank(actor);
        bool reported = c.paused();
        assertTrue(reported == false, "unpaused contract must report paused() == false");
    }
}

