pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address keeper;

    function setUp() public {
        c = new C();
        keeper = address(0xA11CE);
        c.initialize(
            IERC20(address(0x1)),
            IERC20(address(0x2)),
            IRewardRouterV2(address(0x3)),
            IGlpManager(address(0x4)),
            address(0x5),
            keeper
        );
    }

    function testFuzz_property(uint256 seed, uint256 junkAmount) public {
        // bound seed so vm.addr always finds a keeper consistent with deployment
        bound(seed, 0, type(uint160).max);
        address actor = vm.addr(uint160(seed));

        // drive c through the public keeper entry: pause the contract
        vm.prank(actor);
        try c.pauseDeposit() {
            // succeeded only if actor == c.keeper(); otherwise paused state stays false
        } catch {
            // not the keeper; retry with the deployed keeper to ensure the pause actually happens
            vm.prank(keeper);
            c.pauseDeposit();
        }

        // General rule: after a successful pause, the public paused() view must report true.
        // (If pauseDeposit reverted for both, the keeper branch above forced the pause, so paused() is true here.)
        assertTrue(c.paused(), "paused() must reflect the paused state after pausing");
    }
